42	 * A OutputFormat that sends the reduce output to a SQL table.
43	 * <p> 
44	 * {@link DBOutputFormat} accepts &lt;key,value&gt; pairs, where 
45	 * key has a type extending DBWritable. Returned {@link RecordWriter} 
46	 * writes <b>only the key</b> to the database with a batch SQL query.  
47	 * 
48	 */
49	@InterfaceAudience.Public
50	@InterfaceStability.Stable
51	public class DBOutputFormat<K  extends DBWritable, V> 
52	extends OutputFormat<K,V> {
53	
54	  private static final Logger LOG =
55	      LoggerFactory.getLogger(DBOutputFormat.class);
56	  public String dbProductName = "DEFAULT";
57	
58	  public void checkOutputSpecs(JobContext context) 
59	      throws IOException, InterruptedException {}
60	
