67	  /**
68	   * A RecordWriter that writes the reduce output to a SQL table
69	   */
70	  @InterfaceStability.Evolving
71	  public class DBRecordWriter 
72	      extends RecordWriter<K, V> {
73	
74	    private Connection connection;
75	    private PreparedStatement statement;
76	
77	    public DBRecordWriter() throws SQLException {
78	    }
79	
80	    public DBRecordWriter(Connection connection
81	        , PreparedStatement statement) throws SQLException {
82	      this.connection = connection;
83	      this.statement = statement;
84	      this.connection.setAutoCommit(false);
85	    }
86	
87	    public Connection getConnection() {
88	      return connection;
89	    }
90	    
91	    public PreparedStatement getStatement() {
92	      return statement;
93	    }
94	    
95	    /** {@inheritDoc} */
96	    public void close(TaskAttemptContext context) throws IOException {
97	      try {
98	        statement.executeBatch();
99	        connection.commit();
100	      } catch (SQLException e) {
101	        try {
102	          connection.rollback();
103	        }
104	        catch (SQLException ex) {
105	          LOG.warn(StringUtils.stringifyException(ex));
106	        }
107	        throw new IOException(e.getMessage());
108	      } finally {
109	        try {
110	          statement.close();
111	          connection.close();
112	        }
113	        catch (SQLException ex) {
114	          throw new IOException(ex.getMessage());
115	        }
116	      }
117	    }
118	
119	    /** {@inheritDoc} */
120	    public void write(K key, V value) throws IOException {
121	      try {
122	        key.write(statement);
123	        statement.addBatch();
124	      } catch (SQLException e) {
125	        e.printStackTrace();
126	      }
127	    }
128	  }
