130	  /**
131	   * Constructs the query used as the prepared statement to insert data.
132	   * 
133	   * @param table
134	   *          the table to insert into
135	   * @param fieldNames
136	   *          the fields to insert into. If field names are unknown, supply an
137	   *          array of nulls.
138	   */
139	  public String constructQuery(String table, String[] fieldNames) {
140	    if(fieldNames == null) {
141	      throw new IllegalArgumentException("Field names may not be null");
142	    }
143	
144	    StringBuilder query = new StringBuilder();
145	    query.append("INSERT INTO ").append(table);
146	
147	    if (fieldNames.length > 0 && fieldNames[0] != null) {
148	      query.append(" (");
149	      for (int i = 0; i < fieldNames.length; i++) {
150	        query.append(fieldNames[i]);
151	        if (i != fieldNames.length - 1) {
152	          query.append(",");
153	        }
154	      }
155	      query.append(")");
156	    }
157	    query.append(" VALUES (");
158	
159	    for (int i = 0; i < fieldNames.length; i++) {
160	      query.append("?");
161	      if(i != fieldNames.length - 1) {
162	        query.append(",");
163	      }
164	    }
165	
166	    if (dbProductName.startsWith("DB2") || dbProductName.startsWith("ORACLE")) {
167	      query.append(")");
168	    } else {
169	      query.append(");");
170	    }
171	
172	    return query.toString();
173	  }
174	
175	  /** {@inheritDoc} */
176	  public RecordWriter<K, V> getRecordWriter(TaskAttemptContext context) 
177	      throws IOException {
178	    DBConfiguration dbConf = new DBConfiguration(context.getConfiguration());
179	    String tableName = dbConf.getOutputTableName();
180	    String[] fieldNames = dbConf.getOutputFieldNames();
181	    
182	    if(fieldNames == null) {
183	      fieldNames = new String[dbConf.getOutputFieldCount()];
184	    }
185	    
186	    try {
187	      Connection connection = dbConf.getConnection();
188	      PreparedStatement statement = null;
189	
190	      DatabaseMetaData dbMeta = connection.getMetaData();
191	      this.dbProductName = dbMeta.getDatabaseProductName().toUpperCase();
192	
193	      statement = connection.prepareStatement(
194	                    constructQuery(tableName, fieldNames));
195	      return new DBRecordWriter(connection, statement);
196	    } catch (Exception ex) {
197	      throw new IOException(ex.getMessage());
198	    }
199	  }
