201	  /**
202	   * Initializes the reduce-part of the job with 
203	   * the appropriate output settings
204	   * 
205	   * @param job The job
206	   * @param tableName The table to insert data into
207	   * @param fieldNames The field names in the table.
208	   */
209	  public static void setOutput(Job job, String tableName, 
210	      String... fieldNames) throws IOException {
211	    if(fieldNames.length > 0 && fieldNames[0] != null) {
212	      DBConfiguration dbConf = setOutput(job, tableName);
213	      dbConf.setOutputFieldNames(fieldNames);
214	    } else {
215	      if (fieldNames.length > 0) {
216	        setOutput(job, tableName, fieldNames.length);
217	      }
218	      else { 
219	        throw new IllegalArgumentException(
220	          "Field names must be greater than 0");
221	      }
222	    }
223	  }
224	  
225	  /**
226	   * Initializes the reduce-part of the job 
227	   * with the appropriate output settings
228	   * 
229	   * @param job The job
230	   * @param tableName The table to insert data into
231	   * @param fieldCount the number of fields in the table.
232	   */
233	  public static void setOutput(Job job, String tableName, 
234	      int fieldCount) throws IOException {
235	    DBConfiguration dbConf = setOutput(job, tableName);
236	    dbConf.setOutputFieldCount(fieldCount);
237	  }
238	  
239	  private static DBConfiguration setOutput(Job job,
240	      String tableName) throws IOException {
241	    job.setOutputFormatClass(DBOutputFormat.class);
242	    job.setReduceSpeculativeExecution(false);
243	
244	    DBConfiguration dbConf = new DBConfiguration(job.getConfiguration());
245	    
246	    dbConf.setOutputTableName(tableName);
247	    return dbConf;
248	  }
249	}

